import{_ as t,o as e,c as u,a2 as q}from"./chunks/framework.Crpw6aS5.js";const _=JSON.parse('{"title":"2014年 · 复利50年","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2014年.md","filePath":"05_quotes/by-year/2014年.md"}'),a={name:"05_quotes/by-year/2014年.md"};function l(r,o,c,p,b,k){return e(),u("div",null,[...o[0]||(o[0]=[q('<h1 id="_2014年-·-复利50年" tabindex="-1">2014年 · 复利50年 <a class="header-anchor" href="#_2014年-·-复利50年" aria-label="Permalink to &quot;2014年 · 复利50年&quot;">​</a></h1><blockquote><p>&quot;长期来看，以货币计价的工具是风险更高的投资——远比随时间买入并仅产生象征性费用和佣金的广泛多元化股票组合风险更高。&quot;——巴菲特（84岁）</p></blockquote><p>本页收录2014年致股东信中的经典语录。伯克希尔成立50周年，巴菲特与芒格共同撰写纪念长文，回顾从雪茄烟蒂到价值帝国的完整进化路径，并预言未来50年的延续。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;波动性远非风险的同义词。将这两个术语等同的流行公式误导了学生、投资者和CEO。&quot;</p></blockquote><blockquote><p>&quot;长期来看，以货币计价的工具是风险更高的投资——远比随时间买入并仅产生象征性费用和佣金的广泛多元化股票组合风险更高。&quot;</p></blockquote><blockquote><p>&quot;以低价买平庸企业相比，以公平价格买一家出色企业，远比好得多。&quot;</p></blockquote><blockquote><p>&quot;在19家公司的董事任期内，我从没见过投资银行家在向潜在收购方董事会陈述股票换股票交易时量化这一至关重要的数学。相反，银行家的焦点是描述当前收购支付的&#39;惯例&#39;市场溢价——一种绝对愚蠢的评估方式。&quot;</p></blockquote><blockquote><p>&quot;用一家美好企业的股票交换一家平庸企业的所有权，不可修复地摧毁价值。&quot;</p></blockquote><blockquote><p>&quot;如果你不能持有一只股票十年，那就不要考虑持有十分钟。&quot;</p></blockquote><blockquote><p>&quot;频繁交易、试图&#39;择时&#39;、多元化不足、向管理人和顾问支付高额且不必要的费用，以及使用借入资金，都可能摧毁终身股票持有者本应享受的体面回报。&quot;</p></blockquote><blockquote><p>&quot;市场价格的月度或年度走势往往反复无常，并不能反映内在价值的变化。然而，随着时间的推移，股票价格与内在价值几乎必然趋于一致。&quot;</p></blockquote><blockquote><p>&quot;GEICO的成本优势是该公司年复一年蚕食市场份额的因素。公司的低成本创造了一条护城河——一条持久的护城河——竞争对手无法跨越。&quot;</p></blockquote><blockquote><p>&quot;伯克希尔的文化是：虽然形式是公司，但态度是合伙关系。这在石头上。&quot;</p></blockquote><blockquote><p>&quot;查理给我的蓝图很简单：忘掉你所知道的以美好价格购买公平企业；相反，以公平价格购买美好企业。&quot;</p></blockquote><blockquote><p>&quot;在56年里，我们从未有过争执。当我们不同时，查理通常以这句话结束：&#39;沃伦，想清楚，你会同意我，因为你聪明而我是对的。&#39;&quot;</p></blockquote><blockquote><p>&quot;如果投资者进入伯克希尔股票的点异常高，可能许多年后投资者才能实现利润。换言之，如果以抬高价格购买，稳健投资可能变成鲁莽投机。&quot;</p></blockquote><blockquote><p>&quot;波动性≠风险。两者等同是华尔街最流行的谬误之一。高波动性可能恰恰是机会而非风险。&quot;</p></blockquote><blockquote><p>&quot;我们不预测市场。我们不知道明天或明年股市会涨还是会跌。我们的确知道的是：恐惧是投资者最大的敌人，而贪婪是朋友。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2014年是伯克希尔成立50周年，年报首次同时披露账面价值和股价的历史记录。当年股价涨幅27.0%（标普500涨13.7%），账面价值增长8.3%。50年来伯克希尔累计涨幅751,113%，远超标普500的11,196%。本年还收购了Van Tuyl汽车集团（78家汽车经销商），使伯克希尔旗下企业超过其他任何公司。巴菲特明确表示，继任CEO将来自内部候选人，他本人99%的遗产将投入伯克希尔股票。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/2014年/翻译.html">01_letters/2014年/翻译</a> · <a href="/01_letters/2014年/核心总结.html">01_letters/2014年/核心总结</a> · <a href="/01_letters/2014年/思维导图.html">01_letters/2014年/思维导图</a></p>',26)])])}const h=t(a,[["render",l]]);export{_ as __pageData,h as default};
